mkitem!{types ! { #! [unstable (feature = "stdarch_loongarch" , issue = "117427")] # [doc = " 256-bit wide integer vector type, LoongArch-specific"] # [doc = ""] # [doc = " This type is the same as the `__m256i` type defined in `lasxintrin.h`,"] # [doc = " representing a 256-bit SIMD register. Usage of this type typically"] # [doc = " occurs in conjunction with the `lasx` target features for LoongArch."] # [doc = ""] # [doc = " Internally this type may be viewed as:"] # [doc = ""] # [doc = " * `i8x32` - thirty two `i8` values packed together"] # [doc = " * `i16x16` - sixteen `i16` values packed together"] # [doc = " * `i32x8` - eight `i32` values packed together"] # [doc = " * `i64x4` - four `i64` values packed together"] # [doc = ""] # [doc = " (as well as unsigned versions). Each intrinsic may interpret the"] # [doc = " internal bits differently, check the documentation of the intrinsic"] # [doc = " to see how it's being used."] # [doc = ""] # [doc = " The in-memory representation of this type is the same as the one of an"] # [doc = " equivalent array (i.e. the in-memory order of elements is the same, and"] # [doc = " there is no padding); however, the alignment is different and equal to"] # [doc = " the size of the type. Note that the ABI for function calls may *not* be"] # [doc = " the same."] # [doc = ""] # [doc = " Note that this means that an instance of `m256i` typically just means"] # [doc = " a \"bag of bits\" which is left up to interpretation at the point of use."] # [doc = ""] # [doc = " Most intrinsics using `m256i` are prefixed with `lasx_` and the integer"] # [doc = " types tend to correspond to suffixes like \"b\", \"h\", \"w\" or \"d\"."] pub struct m256i (4 x i64) ; # [doc = " 256-bit wide set of eight `f32` values, LoongArch-specific"] # [doc = ""] # [doc = " This type is the same as the `__m256` type defined in `lasxintrin.h`,"] # [doc = " representing a 256-bit SIMD register which internally consists of"] # [doc = " eight packed `f32` instances. Usage of this type typically occurs in"] # [doc = " conjunction with the `lasx` target features for LoongArch."] # [doc = ""] # [doc = " Note that unlike `m256i`, the integer version of the 256-bit registers,"] # [doc = " this `m256` type has *one* interpretation. Each instance of `m256`"] # [doc = " always corresponds to `f32x8`, or eight `f32` values packed together."] # [doc = ""] # [doc = " The in-memory representation of this type is the same as the one of an"] # [doc = " equivalent array (i.e. the in-memory order of elements is the same, and"] # [doc = " there is no padding  between two consecutive elements); however, the"] # [doc = " alignment is different and equal to the size of the type. Note that the"] # [doc = " ABI for function calls may *not* be the same."] # [doc = ""] # [doc = " Most intrinsics using `m256` are prefixed with `lasx_` and are"] # [doc = " suffixed with \"s\"."] pub struct m256 (8 x f32) ; # [doc = " 256-bit wide set of four `f64` values, LoongArch-specific"] # [doc = ""] # [doc = " This type is the same as the `__m256d` type defined in `lasxintrin.h`,"] # [doc = " representing a 256-bit SIMD register which internally consists of"] # [doc = " four packed `f64` instances. Usage of this type typically occurs in"] # [doc = " conjunction with the `lasx` target features for LoongArch."] # [doc = ""] # [doc = " Note that unlike `m256i`, the integer version of the 256-bit registers,"] # [doc = " this `m256d` type has *one* interpretation. Each instance of `m256d`"] # [doc = " always corresponds to `f64x4`, or four `f64` values packed together."] # [doc = ""] # [doc = " The in-memory representation of this type is the same as the one of an"] # [doc = " equivalent array (i.e. the in-memory order of elements is the same, and"] # [doc = " there is no padding); however, the alignment is different and equal to"] # [doc = " the size of the type. Note that the ABI for function calls may *not* be"] # [doc = " the same."] # [doc = ""] # [doc = " Most intrinsics using `m256d` are prefixed with `lasx_` and are suffixed"] # [doc = " with \"d\". Not to be confused with \"d\" which is used for `m256i`."] pub struct m256d (4 x f64) ; }}
